from __future__ import annotations

from .presentation import escape_html as e

from .settings_center import certbot_auto_renewal, certificate_summary, configured_https_domain, role_description, system_summary
from .storage import format_size
from .observability import service_health


def _setting_options(values: dict[str, str], key: str, choices: tuple[tuple[str, str], ...]) -> str:
    defaults = {"date_format": "ymd", "time_format": "24h", "home_page": "/"}
    current = values.get(key, defaults.get(key, ""))
    return "".join(
        f'<option value="{e(value)}" {"selected" if current == value else ""}>{e(label)}</option>'
        for value, label in choices
    )


def _brazil_timezone_options(current: str) -> str:
    choices = (
        ("America/Rio_Branco", "Acre (AC) — Rio Branco"),
        ("America/Eirunepe", "Amazonas (oeste) — Eirunepé"),
        ("America/Manaus", "Amazonas (AM) — Manaus"),
        ("America/Boa_Vista", "Roraima (RR) — Boa Vista"),
        ("America/Porto_Velho", "Rondônia (RO) — Porto Velho"),
        ("America/Cuiaba", "Mato Grosso (MT) — Cuiabá"),
        ("America/Campo_Grande", "Mato Grosso do Sul (MS) — Campo Grande"),
        ("America/Santarem", "Pará (oeste) — Santarém"),
        ("America/Belem", "Amapá e Pará (AP/PA) — Belém"),
        ("America/Fortaleza", "Ceará, Maranhão e Piauí (CE/MA/PI)"),
        ("America/Recife", "Paraíba, Pernambuco e Rio Grande do Norte (PB/PE/RN)"),
        ("America/Maceio", "Alagoas e Sergipe (AL/SE)"),
        ("America/Bahia", "Bahia (BA) — Salvador"),
        ("America/Araguaina", "Tocantins (TO) — Araguaína"),
        ("America/Sao_Paulo", "Brasília, Goiás, Sudeste e Sul (DF/GO/ES/MG/RJ/SP/PR/SC/RS)"),
        ("America/Noronha", "Fernando de Noronha (PE)"),
    )
    if current and current not in {value for value, _ in choices}:
        choices = ((current, f"Fuso atual — {current}"),) + choices
    return "".join(f'<option value="{e(value)}" {"selected" if current == value else ""}>{e(label)}</option>' for value, label in choices)


def settings_tab_content(conn, tab: str, values: dict[str, str], *, local_dt, csrf_token: str, version: str, build_id: str) -> str:
    if tab == "general":
        return f'''<form method="post" action="/settings/general" enctype="multipart/form-data" class="panel settings-form settings-general-form">
          <input type="hidden" name="csrf_token" value="{csrf_token}">
          <div class="panel-title settings-section-title"><span class="settings-title-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="3"/><path d="M19 15a2 2 0 0 0 .4 2l-2.8 2.8a2 2 0 0 0-2-.4A2 2 0 0 0 13 21H9a2 2 0 0 0-1.6-1.6 2 2 0 0 0-2 .4L2.6 17A2 2 0 0 0 3 15.1 2 2 0 0 0 1 13V9a2 2 0 0 0 2-1.6 2 2 0 0 0-.4-2L5.4 2.6A2 2 0 0 0 7.3 3 2 2 0 0 0 9 1h4a2 2 0 0 0 1.6 2 2 2 0 0 0 2-.4l2.8 2.8a2 2 0 0 0-.4 2A2 2 0 0 0 21 9v4a2 2 0 0 0-2 2Z"/></svg></span><div><h2>Configurações gerais</h2><p class="muted">Identidade, localização e experiência inicial.</p></div></div>
          <div class="form-grid">
            <label>Nome da instalação<input name="installation_name" required maxlength="120" value="{e(values.get('installation_name', 'Backup Manager Local'))}"></label>
            <label>Empresa<input name="provider_name" required maxlength="160" value="{e(values.get('provider_name', ''))}"></label>
            <label>Estado e timezone<select name="timezone" required>{_brazil_timezone_options(values.get('timezone', 'America/Sao_Paulo'))}</select><small>Escolha a região onde o servidor está instalado.</small></label>
            <div class="settings-fixed-field"><span>Idioma da interface</span><strong>Português (Brasil)</strong></div>
            <label>Formato de data<select name="date_format">{_setting_options(values, 'date_format', (('dmy', 'DD/MM/AAAA'), ('ymd', 'AAAA-MM-DD')))}</select></label>
            <label>Formato de hora<select name="time_format">{_setting_options(values, 'time_format', (('24h', '24 horas'), ('12h', '12 horas')))}</select></label>
            <label>Página inicial<select name="home_page">{_setting_options(values, 'home_page', (('/', 'Centro de Operações'), ('/backups', 'Backups'), ('/equipment', 'Equipamentos'), ('/reports', 'Relatórios')))}</select></label>
            <label>Contato administrativo<input name="administrative_contact" maxlength="200" value="{e(values.get('administrative_contact', ''))}" placeholder="e-mail ou telefone interno"></label>
          </div>
          <label>Texto institucional<textarea name="institutional_text" rows="4" maxlength="1000">{e(values.get('institutional_text', ''))}</textarea></label>
          <div class="form-actions"><button type="submit">Salvar configurações gerais</button></div>
        </form>'''
    if tab == "users":
        users = conn.execute("""SELECT u.id,u.username,u.full_name,u.is_active,r.slug role_slug,r.name role_name
                              FROM users u JOIN roles r ON r.id=u.role_id ORDER BY u.username""").fetchall()
        rows = "".join(f'''<tr><td data-label="Usuário"><div class="settings-user-cell"><span class="settings-user-avatar">{e((item['full_name'] or item['username'])[:1].upper())}</span><div><strong>{e(item['full_name'])}</strong><small class="table-sub">@{e(item['username'])}</small></div></div></td>
          <td data-label="Perfil"><div class="settings-role-cell"><strong>{e(item['role_name'])}</strong><small class="table-sub">{e(role_description(item['role_slug']))}</small></div></td>
          <td data-label="Status"><span class="badge status-{'success' if item['is_active'] else 'cancelled'}"><i></i>{'Ativo' if item['is_active'] else 'Inativo'}</span></td>
          <td data-label="Ação"><details class="settings-user-editor"><summary class="button small secondary"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="3"/><path d="M19 15a2 2 0 0 0 .4 2l-2.8 2.8a2 2 0 0 0-2-.4A2 2 0 0 0 13 21H9a2 2 0 0 0-1.6-1.6 2 2 0 0 0-2 .4L2.6 17A2 2 0 0 0 3 15.1 2 2 0 0 0 1 13V9a2 2 0 0 0 2-1.6 2 2 0 0 0-.4-2L5.4 2.6A2 2 0 0 0 7.3 3 2 2 0 0 0 9 1h4a2 2 0 0 0 1.6 2 2 2 0 0 0 2-.4l2.8 2.8a2 2 0 0 0-.4 2A2 2 0 0 0 21 9v4a2 2 0 0 0-2 2Z"/></svg>Gerenciar</summary><form method="post" action="/settings/users" class="inline-settings-form">
            <input type="hidden" name="csrf_token" value="{csrf_token}"><input type="hidden" name="user_id" value="{item['id']}">
            <div class="settings-editor-head"><span class="settings-editor-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="8" r="4"/><path d="M5 21a7 7 0 0 1 14 0"/></svg></span><div><strong>Editar usuário</strong><small>Atualize os dados e as permissões da conta.</small></div><span>@{e(item['username'])}</span></div><label>Nome completo<input name="full_name" value="{e(item['full_name'])}" required></label>
            <label>Perfil<select name="role">{''.join(f'<option value="{slug}" {"selected" if item["role_slug"] == slug else ""}>{label}</option>' for slug,label in (("admin","Administrador"),("operator","Operador"),("read_download","Leitura")))}</select></label>
            <label class="check settings-user-active"><input type="checkbox" name="is_active" value="1" {'checked' if item['is_active'] else ''}><span><strong>Usuário ativo</strong><small>Permitir acesso ao painel.</small></span></label>
            <label>Nova senha<input type="password" name="new_password" minlength="10" autocomplete="new-password" placeholder="Opcional"><small>Para trocar a senha, use pelo menos 10 caracteres.</small></label>
            <div class="settings-editor-actions"><button type="submit" name="action" value="update">Salvar alterações</button></div>
          </form></details></td></tr>''' for item in users)
        profile_icons = {
            "admin": '<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',
            "operator": '<circle cx="12" cy="8" r="4"/><path d="M5 21a7 7 0 0 1 14 0M18 8h3M19.5 6.5v3"/>',
            "read_download": '<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20V3H6.5A2.5 2.5 0 0 0 4 5.5v14Z"/><path d="M8 7h8M8 11h6"/>',
        }
        profiles = "".join(f'<article class="profile-card profile-{slug}"><span class="profile-card-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{profile_icons[slug]}</svg></span><div><strong>{label}</strong><p>{e(role_description(slug))}</p></div></article>'
                           for slug, label in (("admin", "Administrador"), ("operator", "Operador"), ("read_download", "Leitura")))
        return f'''<section class="settings-users-head"><div class="settings-users-title"><span class="settings-users-title-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.8M16 3.2a4 4 0 0 1 0 7.6"/></svg></span><div><span class="eyebrow">Controle de acesso</span><h2>Usuários e perfis</h2><p>Gerencie quem pode acessar o sistema e quais operações estão disponíveis.</p></div></div><div class="settings-users-head-actions"><span class="settings-users-count"><strong>{len(users)}</strong> usuários</span><button type="button" class="settings-new-user-button" data-dialog-open="settings-new-user"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="9" cy="8" r="4"/><path d="M3 21a6 6 0 0 1 12 0M18 8v6M15 11h6"/></svg><span>Novo usuário</span></button></div></section><section class="profile-grid">{profiles}</section>
          <section class="panel table-panel settings-users-table"><div class="panel-title"><div><h2>Usuários cadastrados</h2><p class="muted">Contas com acesso ao Backup Manager.</p></div><span><strong>{len(users)}</strong> {'usuário cadastrado' if len(users) == 1 else 'usuários cadastrados'}</span></div>
          <table><thead><tr><th>Usuário</th><th>Perfil</th><th>Status</th><th>Ação</th></tr></thead><tbody>{rows}</tbody></table></section>
          <dialog id="settings-new-user" class="settings-user-dialog"><form method="dialog"><button class="dialog-close" aria-label="Fechar">×</button></form><header><span class="settings-new-user-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="9" cy="8" r="4"/><path d="M3 21a6 6 0 0 1 12 0M18 8v6M15 11h6"/></svg></span><div><span class="eyebrow">Controle de acesso</span><h2>Novo usuário</h2><p>Crie uma conta e defina o perfil de acesso inicial.</p></div></header><form method="post" action="/settings/users" class="settings-form settings-new-user"><input type="hidden" name="csrf_token" value="{csrf_token}"><div class="form-grid"><label>Usuário<input name="username" required pattern="[A-Za-z0-9._-]{{3,40}}" placeholder="Ex.: joao.silva"><small>Use letras, números, ponto, hífen ou sublinhado.</small></label>
            <label>Nome completo<input name="full_name" required maxlength="120"></label>
            <label>Perfil<select name="role"><option value="operator">Operador</option><option value="read_download">Leitura</option><option value="admin">Administrador</option></select></label>
            <label>Senha inicial<input type="password" name="new_password" minlength="6" required autocomplete="new-password" placeholder="Mínimo de 6 caracteres"><small class="settings-password-warning">Recomendamos pelo menos 10 caracteres, combinando letras, números e símbolos.</small></label></div>
            <div class="form-actions"><button type="button" class="secondary" data-dialog-close>Cancelar</button><button type="submit" name="action" value="create">Criar usuário</button></div></form></dialog>'''
    if tab == "access":
        domain = configured_https_domain(values.get("https_domain", ""))
        certificate = certificate_summary(domain) if domain else {"issuer": "-", "issued_at": "", "expires_at": "", "days_remaining": None}
        automatic_renewal = certbot_auto_renewal(domain)
        last = {}
        try:
            last = __import__("json").loads(values.get("https_last_check", "{}"))
        except ValueError:
            pass
        check = lambda key: "verified" if last.get(key) else "pending"
        check_icon = '<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/></svg>'
        if certificate.get("valid"):
            https_actions = '''<button name="action" value="test" type="submit" class="secondary">Testar sem salvar</button><button name="action" value="validate" type="submit">Salvar alterações</button>'''
            confirmation = ""
        else:
            issue_action = '<button name="action" value="issue" type="submit">Emitir certificado</button>' if values.get("https_status") == "ready" else ""
            https_actions = f'''<button name="action" value="test" type="submit" class="secondary">Testar sem salvar</button><button name="action" value="validate" type="submit">Validar e salvar</button>{issue_action}'''
            confirmation = '<label class="check"><input type="checkbox" name="confirm" value="1"> Confirmo a instalação do certificado e a alteração do acesso.</label>' if issue_action else ""
        cert_rows = f'''<dl class="details settings-certificate-details"><dt>Domínio vinculado</dt><dd>{e(domain or 'Nenhum domínio vinculado')}</dd><dt>E-mail administrativo</dt><dd>{e(values.get('https_email', '') or 'Não informado')}</dd><dt>Emissor</dt><dd>{e(certificate.get('issuer') or '-')}</dd>
          <dt>Emitido em</dt><dd>{e(local_dt(certificate.get('issued_at')))}</dd><dt>Expira em</dt><dd>{e(local_dt(certificate.get('expires_at')))}</dd>
          <dt>Dias restantes</dt><dd>{e(certificate.get('days_remaining') if certificate.get('days_remaining') is not None else '-')}</dd>
          <dt>Renovação automática</dt><dd><span class="badge status-{'success' if automatic_renewal else 'cancelled'}">{'Ativa' if automatic_renewal else 'Não configurada'}</span></dd><dt>Última renovação</dt><dd>{e(local_dt(values.get('https_last_renewal', '') or certificate.get('issued_at', '')))}</dd></dl>'''
        return f'''<section class="settings-access-head"><div><span class="settings-access-head-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="11" width="18" height="10" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg></span><div><span class="eyebrow">Conexão segura</span><h2>Acesso e HTTPS</h2><p>Configure um domínio e proteja o acesso ao painel com certificado TLS.</p></div></div><span class="badge status-{'success' if certificate.get('valid') else 'cancelled'}">{'Protegido' if certificate.get('valid') else 'Não configurado'}</span></section><section class="grid-two settings-access-grid"><form method="post" action="/settings/https" class="panel settings-form settings-https-assistant">
          <input type="hidden" name="csrf_token" value="{csrf_token}"><div class="panel-title"><div><h2>Configurar acesso seguro</h2><p class="muted">Use um domínio público apontado para este servidor.</p></div></div>
          <div class="form-grid"><label>Domínio<input name="domain" value="{e(domain)}" placeholder="backup.exemplo.com.br" required><small>Informe somente o domínio, sem http:// ou caminhos.</small></label>
          <label>E-mail administrativo<input name="email" type="email" value="{e(values.get('https_email', ''))}" required><small>Usado pelo Let's Encrypt para avisos do certificado.</small></label></div>
          <div class="https-checks"><span class="{check('resolves')}">{check_icon}<b>Domínio resolve</b><small>DNS direcionado ao servidor</small></span><span class="{check('port_80')}">{check_icon}<b>Porta 80 acessível</b><small>Validação externa disponível</small></span>
          <span class="{check('port_443')}">{check_icon}<b>Porta 443 acessível</b><small>Acesso HTTPS disponível</small></span><span class="{check('certificate_valid')}">{check_icon}<b>Certificado válido</b><small>TLS reconhecido pelo navegador</small></span><span class="{check('nginx_configured')}">{check_icon}<b>Servidor HTTPS</b><small>Pronto para acesso seguro</small></span></div>
          {confirmation}
          <div class="actions settings-https-actions">{https_actions}</div>
          <p class="muted settings-https-footnote">O assistente utiliza Let's Encrypt e nunca cria certificados autoassinados.</p>
        </form><article class="panel settings-certificate-card"><div class="settings-certificate-title"><span><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/></svg></span><div><h2>Certificado atual</h2><p>Informações do certificado instalado.</p></div></div>{cert_rows}</article></section>'''
    if tab == "backup":
        policy = conn.execute("SELECT * FROM retention_policies WHERE equipment_id IS NULL").fetchone()
        jobs = conn.execute("SELECT COUNT(*) FROM backup_jobs WHERE deleted_at IS NULL AND status='active'").fetchone()[0]
        backup_counts = conn.execute("SELECT SUM(CASE WHEN backup_status='available' THEN 1 ELSE 0 END) available,SUM(CASE WHEN backup_status='trashed' THEN 1 ELSE 0 END) trashed FROM backups").fetchone()
        icon = lambda path: f'<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{path}</svg>'
        return f'''<section class="settings-backup-head"><span class="settings-backup-head-icon">{icon('<path d="M21 8v13H3V8M1 3h22v5H1zM10 12h4"/>')}</span><div><span class="eyebrow">Proteção dos dados</span><h2>Backup e retenção</h2><p>Gerencie rotinas automáticas e o tempo de armazenamento dos arquivos.</p></div></section>
          <section class="settings-backup-stats"><article class="backup-stat-schedule"><i>{icon('<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>')}</i><div><span>Agendamentos ativos</span><strong>{jobs}</strong><small>Programações habilitadas</small></div></article><article class="backup-stat-files"><i>{icon('<path d="M6 2h9l4 4v16H6a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2Z"/><path d="M14 2v5h5M9 13h6M9 17h6"/>')}</i><div><span>Backups disponíveis</span><strong>{int(backup_counts['available'] or 0)}</strong><small>Arquivos prontos para uso</small></div></article><article class="backup-stat-trash"><i>{icon('<path d="M4 7h16M9 7V4h6v3M7 7l1 14h8l1-14"/>')}</i><div><span>Itens na lixeira</span><strong>{int(backup_counts['trashed'] or 0)}</strong><small>Disponíveis para restauração</small></div></article></section>
          <section class="settings-backup-grid"><article class="panel settings-backup-card settings-backup-automatic"><header><span class="settings-backup-card-icon automatic">{icon('<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>')}</span><div><span class="eyebrow">Automação</span><h2>Backup automático</h2><p>Configure horários e acompanhe as rotinas dos equipamentos.</p></div><span class="badge status-success">Operacional</span></header><div><dl><dt>Agendamentos ativos</dt><dd><strong>{jobs}</strong></dd><dt>Armazenamento</dt><dd>Gerenciado pelo sistema</dd><dt>Limite de envio</dt><dd>{format_size(int(values.get('maximum_upload_size', '0') or 0))}</dd></dl></div><a class="button secondary settings-backup-action" href="/jobs">{icon('<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>')}<span>Gerenciar agendamentos</span><b>›</b></a></article>
          <article class="panel settings-backup-card settings-backup-retention"><header><span class="settings-backup-card-icon retention">{icon('<path d="M4 7h16M9 7V4h6v3M7 7l1 14h8l1-14M10 11v6M14 11v6"/>')}</span><div><span class="eyebrow">Ciclo de vida</span><h2>Retenção e limpeza</h2><p>Defina por quanto tempo os arquivos devem permanecer armazenados.</p></div><span class="badge status-{'success' if policy and policy['is_enabled'] else 'cancelled'}">{'Ativa' if policy and policy['is_enabled'] else 'Inativa'}</span></header><div><dl><dt>Idade máxima</dt><dd><strong>{e(str(policy['max_age_days']) + ' dias' if policy else '-')}</strong></dd><dt>Tempo na lixeira</dt><dd>{e(str(policy['trash_retention_days']) + ' dias' if policy else '-')}</dd><dt>Limpeza automática</dt><dd>{'Habilitada' if policy and policy['is_enabled'] else 'Desabilitada'}</dd></dl></div><a class="button secondary settings-backup-action retention" href="/lifecycle">{icon('<path d="M4 7h16M9 7V4h6v3M7 7l1 14h8l1-14"/>')}<span>Gerenciar retenção</span><b>›</b></a></article></section>'''
    if tab == "drive":
        target = conn.execute("""SELECT t.name,t.is_active,c.remote_name,c.base_path,c.status FROM cloud_targets t
                               JOIN rclone_connections c ON c.target_id=t.id
                               WHERE t.deleted_at IS NULL ORDER BY t.id DESC LIMIT 1""").fetchone()
        connected = bool(target and target['is_active'] and target['status'] in ('configured', 'verified'))
        icon = lambda path: f'<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{path}</svg>'
        return f'''<section class="settings-drive-head"><span class="settings-drive-head-icon">{icon('<path d="M7 18h11a4 4 0 1 1 0-8h.6A6 6 0 0 1 19 12"/><path d="m9 14 3-3 3 3M12 11v8"/>')}</span><div><span class="eyebrow">Cópia externa</span><h2>rclone</h2><p>Envie cópias para S3, B2, SFTP e outros provedores compatíveis.</p></div><span class="badge status-{'success' if connected else 'cancelled'}">{'Conectado' if connected else 'Não conectado'}</span></section>
          <section class="settings-drive-stats"><article><i>{icon('<path d="M7 18h11a4 4 0 0 0 .5-8 7 7 0 0 0-13-1A4.5 4.5 0 0 0 7 18Z"/>')}</i><div><span>Conexão</span><strong>{'Ativa' if connected else 'Pendente'}</strong><small>Remote gerenciado pelo rclone</small></div></article><article><i>{icon('<path d="M4 5h16v14H4zM8 9h8M8 13h5"/>')}</i><div><span>Destino</span><strong>{e(target['name'] if target else 'Não configurado')}</strong><small>Local das cópias externas</small></div></article><article><i>{icon('<path d="M4 12a8 8 0 0 1 14-5l2 2M20 4v5h-5M20 12a8 8 0 0 1-14 5l-2-2M4 20v-5h5"/>')}</i><div><span>Sincronização</span><strong>{'Habilitada' if target and target['is_active'] else 'Desabilitada'}</strong><small>Envio automático de cópias</small></div></article></section>
          <section class="settings-drive-grid"><article class="panel settings-drive-card"><div class="settings-drive-card-title"><span>{icon('<path d="M7 18h11a4 4 0 0 0 .5-8 7 7 0 0 0-13-1A4.5 4.5 0 0 0 7 18Z"/><path d="m9 14 3-3 3 3M12 11v8"/>')}</span><div><span class="eyebrow">Integração</span><h2>Destino externo</h2><p>Configuração atualmente vinculada ao Backup Manager.</p></div><span class="settings-drive-connection-dot {'active' if connected else ''}"></span></div><dl class="settings-drive-details"><dt>Destino configurado</dt><dd>{e(target['name'] if target else 'Não configurado')}</dd><dt>Remote rclone</dt><dd>{e(target['remote_name'] if target else 'Nenhum remote')}</dd><dt>Pasta</dt><dd>{e(target['base_path'] if target else '-')}</dd><dt>Estado da conexão</dt><dd><span class="badge status-{'success' if connected else 'cancelled'}">{'Ativa' if connected else 'Desconectada'}</span></dd><dt>Envio de cópias</dt><dd>{'Habilitado' if target and target['is_active'] else 'Desabilitado'}</dd></dl><a class="button settings-drive-action" href="/cloud"><i>{icon('<path d="M4 12a8 8 0 0 1 14-5l2 2M20 4v5h-5M20 12a8 8 0 0 1-14 5l-2-2M4 20v-5h5"/>')}</i><strong>Gerenciar sincronização</strong>{icon('<path d="m9 6 6 6-6 6"/>')}</a></article>
          <aside class="panel settings-drive-info"><span class="settings-drive-info-icon">{icon('<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>')}</span><div><span class="eyebrow">Segurança</span><h2>Cópia externa protegida</h2><p>Os arquivos locais são preservados enquanto uma cópia é enviada conforme as regras configuradas.</p></div><ul><li>Os backups locais continuam disponíveis.</li><li>As credenciais ficam no arquivo protegido do rclone.</li><li>Falhas e tentativas aparecem no histórico.</li><li>O Backup Manager não executa comandos livres.</li></ul><a href="/reports/storage">Ver relatório de armazenamento <b>›</b></a></aside></section>'''
    if tab == "notifications":
        channel = conn.execute("SELECT is_enabled,last_status,last_test_at FROM notification_channels WHERE channel_type='telegram'").fetchone()
        enabled = bool(channel and channel['is_enabled'])
